start.slots.py:
"""Appointment slots: one every 15 minutes between opening and closing."""

OPEN, CLOSE, STEP = 480, 1080, 15   # minutes after midnight


def next_slot(minute_of_day):
    """First free slot at or after the given minute; tomorrow's opening if today is over. Returns (day_offset, minute)."""
    if minute_of_day < OPEN:
        return (0, OPEN)
    k = -(-(minute_of_day - OPEN) // STEP)
    slot = OPEN + k * STEP
    if slot >= CLOSE:
        return (1, OPEN)
    return (0, slot)

