"""Loyalty points earned per purchase."""

TIERS = [(0, 1.0), (1000, 1.25), (5000, 1.5)]   # (lifetime spend threshold, multiplier)
CAP = 400          # max points from one purchase


def multiplier(lifetime):
    m = 1.0
    for threshold, mult in TIERS:
        if lifetime >= threshold:
            m = mult
    return m


def points(amount, lifetime):
    earned = int(amount * multiplier(lifetime))
    return min(earned, CAP)

