"""Shipping cost calculator for the shop."""
import math

ZONES = {'north': 4.5, 'south': 5.25, 'islands': 11.5}
PER_KG = 0.9
FREE_OVER = 80


def shipping(zone, kg, order_total):
    """Free shipping on orders of 80 or more; otherwise zone fee plus a per-kg charge (whole kilos, rounded up)."""
    if order_total > FREE_OVER:
        return 0
    return round(ZONES[zone] + PER_KG * math.ceil(kg), 2)

