start.opts.py:
"""Parse 'key=value,key=value' option strings."""

DEFAULTS = {'retries': 3, 'verbose': False, 'region': 'eu'}


def parse(opts):
    out = dict(DEFAULTS)
    for part in opts.split(","):
        if "=" not in part:
            continue
        k, v = part.split("=", 1)
        k = k.strip()
        if k not in DEFAULTS:
            continue
        if isinstance(DEFAULTS[k], bool):
            out[k] = v.strip().lower() in ("1", "true", "yes")
        elif isinstance(DEFAULTS[k], int):
            out[k] = int(v)
        else:
            out[k] = v.strip()
    return out

